import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";
import fs from "fs";
import path from "path";
import { INSIGHTS_SECTIONS, insightsCardPath } from "./src/insights/cards";
import { LEDGER_VIEWS, ledgerViewPath } from "./src/ledger/views";
import { routePath } from "./src/utils/routes";

// The sidebar declares paths without the base URL; the plugin adds it.
const RELEASES_ROOT_PATH = "/releases";

// Returns an autogenerated sidebar item only when the directory exists.
// This makes the sidebar resilient to schemas that lack certain type categories
// (e.g. no interfaces or inputs in a simple domain model).
function autoDir(dirName: string) {
  const abs = path.join(__dirname, "docs", dirName);
  return fs.existsSync(abs) ? [{ type: "autogenerated" as const, dirName }] : [];
}

export const insightsSidebar = INSIGHTS_SECTIONS.map((section) => ({
  type: "category" as const,
  label: section.label,
  items: section.cards.map((card) => ({
    type: "link" as const,
    label: card.label,
    href: insightsCardPath(card.id),
  })),
}));

type LedgerLink = { type: "link"; label: string; href: string };
type LedgerCategory = { type: "category"; label: string; items: LedgerLink[] };

/**
 * Builds the ledger sidebar. It is empty when `npm run doc` staged no `static/ledger.db`.
 *
 * A section opens a category and the views after it join the one above, so the
 * order in LEDGER_VIEWS is the order the sidebar shows. The accumulator is built
 * in place; every branch adds to it rather than replacing it.
 *
 * @returns The sidebar items.
 */
function buildLedgerSidebar(): (LedgerLink | LedgerCategory)[] {
  const ledgerPath = path.join(__dirname, "static", "ledger.db");
  if (!fs.existsSync(ledgerPath)) {
    return [];
  }
  return LEDGER_VIEWS.reduce<(LedgerLink | LedgerCategory)[]>((items, view) => {
    const link: LedgerLink = {
      type: "link",
      label: view.label,
      href: ledgerViewPath(view.id),
    };
    const previousItem = items.at(-1);
    if (view.section === null) {
      items.push(link);
    } else if (previousItem?.type === "category" && previousItem.label === view.section) {
      previousItem.items.push(link);
    } else {
      items.push({ type: "category", label: view.section, items: [link] });
    }
    return items;
  }, []);
}

export const ledgerSidebar = buildLedgerSidebar();

/**
 * Reads the release tags that `scripts/stage-releases.js` staged, newest first.
 *
 * @returns The tags, or an empty list when no releases are staged.
 */
function readReleaseTags(): string[] {
  const listPath = path.join(__dirname, "static", "releases", "releases.json");
  if (!fs.existsSync(listPath)) {
    return [];
  }
  const list = fs.readFileSync(listPath, "utf8");
  return JSON.parse(list) as string[];
}

/**
 * Returns the sidebar link of a release. The newest release is served at the root.
 *
 * @param tag - The release tag.
 * @param index - The release's position in the list, newest first.
 * @returns The link.
 */
function releaseLink(tag: string, index: number) {
  let segment: string | null = encodeURIComponent(tag);
  if (index === 0) {
    segment = null;
  }
  return {
    type: "link" as const,
    label: tag,
    href: routePath(RELEASES_ROOT_PATH, segment),
  };
}

const releaseTags = readReleaseTags();
export const releasesSidebar = releaseTags.map(releaseLink);

const sidebars: SidebarsConfig = {
  docsSidebar: [
    "elements/schema",
    {
      type: "category" as const,
      label: "Types",
      items: [
        {
          type: "category" as const,
          label: "Field Containers",
          items: [
            { type: "category" as const, label: "Objects", items: autoDir("elements/types/objects") },
            { type: "category" as const, label: "Interfaces", items: autoDir("elements/types/interfaces") },
            { type: "category" as const, label: "Inputs", items: autoDir("elements/types/inputs") },
          ].filter((c) => c.items.length > 0),
        },
        { type: "category" as const, label: "Enums", items: autoDir("elements/types/enums") },
        { type: "category" as const, label: "Scalars", items: autoDir("elements/types/scalars") },
        { type: "category" as const, label: "Queries", items: autoDir("elements/operations/queries") },
      ].filter((c) => "items" in c && (c.items as unknown[]).length > 0),
    },
    {
      type: "category" as const,
      label: "Other",
      items: [
        { type: "category" as const, label: "Directives", items: autoDir("elements/types/directives") },
      ].filter((c) => c.items.length > 0),
    },
  ],
  insightsSidebar,
  ledgerSidebar,
  releasesSidebar,
};

export default sidebars;
